CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `detallepc_menu`  AS SELECT `producto`.`idproducto` AS `idproducto`, `producto`.`nombre_pro` AS `nombre_pro`, `producto`.`descripcion_pro` AS `descripcion_pro`, `producto`.`precio_pro` AS `precio_pro`, `producto`.`ubicacion_pro` AS `ubicacion_pro`, `producto`.`horario_pro` AS `horario_pro`, `producto`.`foto_pro` AS `foto_pro`, `producto`.`idvendedor` AS `idvendedor`, `vendedor`.`nombre_ven` AS `nombre_ven`, `vendedor`.`telefono_ven` AS `telefono_ven` FROM (`producto` join `vendedor`) WHERE `producto`.`idvendedor` = `vendedor`.`idvendedor` ;

