--
-- Disparadores `calificaciones`
--
DELIMITER $$
CREATE TRIGGER `after_calificaciones_delete` AFTER DELETE ON `calificaciones` FOR EACH ROW BEGIN 
    DELETE FROM estado_alumno 		  WHERE OLD.idcalificacion  = idcalificacion;
	DELETE FROM clasificacion_alumno  WHERE OLD.idcalificacion = idcalificacion;
    DELETE FROM becas 				  WHERE OLD.fk_idalumno = idalumno;
    CALL clasificacion();
    CALL escuela_bd.asignar_becas();
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_estado_insert` AFTER INSERT ON `calificaciones` FOR EACH ROW BEGIN
	
    DECLARE tpromedio DECIMAL;
    DECLARE tidgrupo INTEGER DEFAULT 0;
    
    SELECT fk_idgrupo INTO tidgrupo FROM alumnos, calificaciones WHERE NEW.fk_idalumno=idalumno GROUP BY idalumno;
    SELECT promedio INTO tpromedio FROM calificaciones WHERE idcalificacion=NEW.idcalificacion;
    
    IF tpromedio >= 70 THEN
		INSERT INTO estado_alumno(idcalificacion, promedio, estado_alumno, idalumno, idmateria,idgrupo)
		VALUES (NEW.idcalificacion, NEW.promedio,'APROBADO', NEW.fk_idalumno, NEW.fk_idmateria,tidgrupo);
    ELSE
        INSERT INTO estado_alumno(idcalificacion, promedio, estado_alumno, idalumno, idmateria,idgrupo)
		VALUES (NEW.idcalificacion, NEW.promedio,'REPROBADO', NEW.fk_idalumno, NEW.fk_idmateria,tidgrupo);
	END IF;
    CALL clasificacion();
    CALL escuela_bd.asignar_becas();
    
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_estado_update` AFTER UPDATE ON `calificaciones` FOR EACH ROW BEGIN

    DECLARE tpromedio DECIMAL;
    DECLARE tidgrupo INTEGER DEFAULT 0;
    
    /*SELECT fk_idgrupo INTO tidgrupo FROM alumnos WHERE fk_idalumno=NEW.fk_idalumno;*/
    
    SELECT fk_idgrupo INTO tidgrupo FROM alumnos, calificaciones WHERE NEW.fk_idalumno=idalumno GROUP BY idalumno;
    
    SELECT promedio INTO tpromedio FROM calificaciones WHERE idcalificacion=NEW.idcalificacion;
    
    IF tpromedio >= 70 THEN
		UPDATE estado_alumno SET idcalificacion=NEW.idcalificacion, promedio= NEW.promedio,
        estado_alumno='APROBADO', idalumno=NEW.fk_idalumno, idmateria=NEW.fk_idmateria , idgrupo=tidgrupo
        WHERE idcalificacion=NEW.idcalificacion;
        
        DELETE FROM clasificacion_alumno WHERE idcalificacion=NEW.idcalificacion;
        DELETE FROM becas WHERE idalumno=NEW.fk_idalumno;
    ELSE
       UPDATE estado_alumno SET idcalificacion=NEW.idcalificacion, promedio= NEW.promedio,
        estado_alumno='REPROBADO', idalumno=NEW.fk_idalumno, idmateria=NEW.fk_idmateria, idgrupo=tidgrupo
        WHERE idcalificacion=NEW.idcalificacion;
        
        DELETE FROM clasificacion_alumno WHERE idcalificacion=NEW.idcalificacion;
        DELETE FROM becas WHERE idalumno=NEW.fk_idalumno;
	END IF;
    CALL clasificacion();
    CALL escuela_bd.asignar_becas();
    
    
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `before_calificaciones_update` BEFORE UPDATE ON `calificaciones` FOR EACH ROW BEGIN
INSERT INTO historial_calificaciones(idcalificacion,old_tareas,new_tareas,old_examen1,new_examen1,old_examen2,new_examen2,old_proyecto,new_proyecto,idmateria,idalumno,fecha_cambio)
VALUES (OLD.idcalificacion, OLD.tareas, NEW.tareas, OLD.examen1, NEW.examen1, OLD.examen2, NEW.examen2, OLD.proyecto, NEW.proyecto,OLD.fk_idmateria,OLD.fk_idalumno, SYSDATE());
END
$$
DELIMITER ;

