--
-- Estructura para la vista `calificar_alumnos`
--
DROP TABLE IF EXISTS `calificar_alumnos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `calificar_alumnos`  AS SELECT `grupos`.`fk_idmaestro` AS `fk_idmaestro`, `alumnos`.`idalumno` AS `idalumno`, `alumnos`.`nombre_alum` AS `nombre_alum`, `materias`.`idmateria` AS `idmateria`, `materias`.`nombre_mat` AS `nombre_mat`, `alumnos`.`fk_idgrupo` AS `fk_idgrupo`, `calificaciones`.`idcalificacion` AS `idcalificacion`, `calificaciones`.`tareas` AS `tareas`, `calificaciones`.`examen1` AS `examen1`, `calificaciones`.`examen2` AS `examen2`, `calificaciones`.`proyecto` AS `proyecto`, `calificaciones`.`fk_idmateria` AS `fk_idmateria`, `calificaciones`.`fk_idalumno` AS `fk_idalumno` FROM (((`calificaciones` join `alumnos`) join `materias`) join `grupos`) WHERE `alumnos`.`idalumno` = `calificaciones`.`fk_idalumno` AND `alumnos`.`fk_idgrupo` = `grupos`.`idgrupo` AND `materias`.`idmateria` = `calificaciones`.`fk_idmateria` ORDER BY `alumnos`.`idalumno` ASC ;

-- --------------------------------------------------------

--
-- Estructura para la vista `lista_alumnos`
--
DROP TABLE IF EXISTS `lista_alumnos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `lista_alumnos`  AS SELECT `alumnos`.`idalumno` AS `idalumno`, `alumnos`.`nombre_alum` AS `nombre_alum`, `alumnos`.`edad_alum` AS `edad_alum`, `alumnos`.`sexo_alum` AS `sexo_alum`, `alumnos`.`telefono_alum` AS `telefono_alum`, `alumnos`.`correo_alum` AS `correo_alum`, `alumnos`.`password_alum` AS `password_alum`, `alumnos`.`fk_idgrupo` AS `fk_idgrupo`, `grupos`.`idgrupo` AS `idgrupo`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`grado_grup` AS `grado_grup`, `grupos`.`fk_idmaestro` AS `fk_idmaestro` FROM (`alumnos` join `grupos`) WHERE `alumnos`.`fk_idgrupo` = `grupos`.`idgrupo` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `migrupo`
--
DROP TABLE IF EXISTS `migrupo`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `migrupo`  AS SELECT `maestros`.`idmaestro` AS `idmaestro`, `maestros`.`nombre_maes` AS `nombre_maes`, `grupos`.`idgrupo` AS `idgrupo`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`grado_grup` AS `grado_grup`, count(`alumnos`.`idalumno`) AS `total_alumnos` FROM ((`alumnos` join `grupos`) join `maestros`) WHERE `alumnos`.`fk_idgrupo` = `grupos`.`idgrupo` AND `grupos`.`fk_idmaestro` = `maestros`.`idmaestro` GROUP BY `maestros`.`idmaestro` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `migrupo_alumno`
--
DROP TABLE IF EXISTS `migrupo_alumno`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `migrupo_alumno`  AS SELECT `grupos`.`idgrupo` AS `idgrupo`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`grado_grup` AS `grado_grup`, `grupos`.`fk_idmaestro` AS `fk_idmaestro`, `maestros`.`idmaestro` AS `idmaestro`, `maestros`.`nombre_maes` AS `nombre_maes` FROM (`grupos` join `maestros`) WHERE `grupos`.`fk_idmaestro` = `maestros`.`idmaestro` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `mismaterias`
--
DROP TABLE IF EXISTS `mismaterias`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `mismaterias`  AS SELECT `grupos`.`fk_idmaestro` AS `fk_idmaestro`, `grupos`.`idgrupo` AS `idgrupo`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`grado_grup` AS `grado_grup`, `materias`.`idmateria` AS `idmateria`, `materias`.`nombre_mat` AS `nombre_mat` FROM (`materias` join `grupos`) WHERE `materias`.`grado_mat` = `grupos`.`grado_grup` AND `grupos`.`fk_idmaestro` = `grupos`.`fk_idmaestro` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `mis_alumnos`
--
DROP TABLE IF EXISTS `mis_alumnos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `mis_alumnos`  AS SELECT `maestros`.`idmaestro` AS `idmaestro`, `maestros`.`nombre_maes` AS `nombre_maes`, `alumnos`.`idalumno` AS `idalumno`, `alumnos`.`nombre_alum` AS `nombre_alum`, `alumnos`.`edad_alum` AS `edad_alum`, `alumnos`.`sexo_alum` AS `sexo_alum`, `alumnos`.`telefono_alum` AS `telefono_alum`, `alumnos`.`correo_alum` AS `correo_alum`, `alumnos`.`fk_idgrupo` AS `fk_idgrupo`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`idgrupo` AS `idgrupo` FROM ((`alumnos` join `grupos`) join `maestros`) WHERE `alumnos`.`fk_idgrupo` = `grupos`.`idgrupo` AND `grupos`.`fk_idmaestro` = `maestros`.`idmaestro` ;

-- --------------------------------------------------------

--
-- Estructura para la vista `promedios_materias`
--
DROP TABLE IF EXISTS `promedios_materias`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `promedios_materias`  AS SELECT `calificaciones`.`fk_idalumno` AS `fk_idalumno`, `alumnos`.`nombre_alum` AS `nombre_alum`, `calificaciones`.`idcalificacion` AS `idcalificacion`, (`calificaciones`.`tareas` + `calificaciones`.`examen1` + `calificaciones`.`examen2` + `calificaciones`.`proyecto`) / 4 AS `promedio`, `calificaciones`.`fk_idmateria` AS `fk_idmateria`, `materias`.`nombre_mat` AS `nombre_mat`, `grupos`.`nombre_grup` AS `nombre_grup`, `grupos`.`fk_idmaestro` AS `fk_idmaestro`, `alumnos`.`fk_idgrupo` AS `fk_idgrupo` FROM (((`calificaciones` join `alumnos`) join `materias`) join `grupos`) WHERE `alumnos`.`idalumno` = `calificaciones`.`fk_idalumno` AND `materias`.`idmateria` = `calificaciones`.`fk_idmateria` AND `alumnos`.`fk_idgrupo` = `grupos`.`idgrupo` ORDER BY `alumnos`.`idalumno` ASC ;

