--
-- Estructura Stand-in para la vista `vendedor_ventas`
-- (Véase abajo para la vista actual)
--
CREATE TABLE `vendedor_ventas` (
`idvendedor` int(11)
,`nombre` varchar(45)
,`num_pedidos` bigint(21)
,`piezas_vendidas` decimal(41,0)
,`monto_total` decimal(32,0)
,`promedio_venta` decimal(14,4)
);

-- --------------------------------------------------------

--
-- Estructura para la vista `vendedor_ventas`
--
DROP TABLE IF EXISTS `vendedor_ventas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vendedor_ventas`  AS SELECT `vendedor`.`idvendedor` AS `idvendedor`, `vendedor`.`nombre` AS `nombre`, count(`pedido`.`idpedido`) AS `num_pedidos`, sum(`pedido`.`cantidad`) AS `piezas_vendidas`, sum(`pedido`.`monto_total`) AS `monto_total`, avg(`pedido`.`monto_total`) AS `promedio_venta` FROM (`vendedor` join `pedido`) WHERE `vendedor`.`idvendedor` = `pedido`.`idvendedor` GROUP BY `pedido`.`idvendedor` ORDER BY avg(`pedido`.`monto_total`) DESC ;

